      [MATCH_ROOM]: defineRoom(MatchRoom).filterBy(["code", "createToken"]),
      // Standalone duels (the combat spike) are admitted the same way, under their own name.
      [DUEL_ROOM]: defineRoom(DuelRoom).filterBy(["code", "createToken"]),
    },
    ...(options.testPlacement === true ? { routes: createRouter({ placeShipEndpoint }) } : {}),
  });
  await server.listen(options.port, options.host);
  const address = server.transport.server?.address() as AddressInfo | null | undefined;
  return {
    port: address?.port ?? options.port,
    server,
    close: () => server.gracefullyShutdown(false),
  };
}
import { DEFAULT_PORT, startGameServer } from "./server.js";

const port = Number(process.env["PORT"] ?? DEFAULT_PORT);
const running = await startGameServer({ port });
console.log(`Pirate Sea Race server listening on ws://localhost:${running.port}`);
export { authorizeEntry, DUEL_RESULT_TICKS, MatchRoom, type MatchMetadata, type SeaDuelDiagnostics } from "./MatchRoom.js";
export { InputGate, type DropReason } from "./inputGate.js";
export { authorizeDuelEntry, DuelRoom } from "./DuelRoom.js";
export { DELAY_DECISION_FRAMES, DuelMachine, type DuelDiagnostics, type DuelLobbySchema, type DuelOutcome } from "./duelMachine.js";
export { DuelInputGate } from "./duelInputGate.js";
export { generateMatchCode } from "./matchCode.js";
export {
  DuelMarkerSchema,
  DuelRoomStateSchema,
  DuelSeatSchema,
  GrappleSchema,
  MatchStateSchema,
  PlayerStatusSchema,
  SeaDuelSchema,
  ShipSchema,
} from "./schema.js";
export { DEFAULT_PORT, MAX_FRAME_BYTES, startGameServer, type GameServerOptions, type RunningGameServer } from "./server.js";
