/** A map as the converter writes it (`scripts/build-map.ts`): rows of terrain characters plus the named objects. */
export interface SeaMapSource {
  readonly name: string;
  readonly widthTiles: number;
  readonly heightTiles: number;
  readonly rows: readonly string[];
  readonly islands: readonly IslandSource[];
  /** In slot order. */
  readonly spawnSlots: readonly SpawnSlot[];
  /** The shared crossing near the centre that every route between islands passes (§3: ships meet). */
  readonly hub: TilePoint;
  /** The hidden final-island sockets, in the order they are authored. Absent means none. */
  readonly finalSockets?: readonly FinalSocket[];
}

/** A dock tile, owned by the island whose rectangle holds it. `side` (N, E, S or W) says where it lies on the island. */
export interface Dock {
  readonly id: number;
  readonly tileX: number;
  readonly tileY: number;
  readonly island: number;
  readonly side: Compass;
}

/** A decoded map, as the simulation and the client read it. */
export interface SeaMapDefinition {
  readonly name: string;
  readonly widthTiles: number;
  readonly heightTiles: number;
  readonly subUnitsPerTile: number;
  /** Row-major terrain, `widthTiles * heightTiles` entries. */
  readonly terrain: readonly Terrain[];
  readonly islands: readonly IslandSource[];
  /** Row-major order of their tiles. */
  readonly docks: readonly Dock[];
  readonly spawnSlots: readonly SpawnSlot[];
  readonly hub: TilePoint;
  /** Their land belongs to no island and holds no dock, so docks, sailing and respawn ignore them. */
  readonly finalSockets: readonly FinalSocket[];
}

/** Decodes a map source. Throws on a structural error (a row of the wrong length, an unknown character). */
export function createSeaMap(source: SeaMapSource): SeaMapDefinition {
  if (source.rows.length !== source.heightTiles) {
    throw new Error(`${source.name}: ${source.rows.length} rows for a height of ${source.heightTiles}`);
  }
  const terrain: Terrain[] = [];
  source.rows.forEach((row, tileY) => {
    if (row.length !== source.widthTiles) throw new Error(`${source.name}: row ${tileY} has ${row.length} tiles, not ${source.widthTiles}`);
    for (const char of row) {
      const kind = TERRAIN_CHARS[char];
      if (kind === undefined) throw new Error(`${source.name}: unknown terrain "${char}" in row ${tileY}`);
      terrain.push(kind);
    }
  });
  const docks: Dock[] = [];
  terrain.forEach((kind, index) => {
    if (kind !== Terrain.Dock) return;
    const tileX = index % source.widthTiles;
    const tileY = Math.floor(index / source.widthTiles);
    const island = source.islands.findIndex((candidate) => insideIsland(candidate, tileX, tileY));
    const side = island < 0 ? "N" : sideOf(source.islands[island]!, tileX, tileY);
    docks.push({ id: docks.length, tileX, tileY, island, side });
  });
  return {
    name: source.name,
    widthTiles: source.widthTiles,
    heightTiles: source.heightTiles,
    subUnitsPerTile: SUB_UNITS_PER_TILE,
    terrain,
    islands: source.islands,
    docks,
    spawnSlots: source.spawnSlots,
    hub: source.hub,
    finalSockets: source.finalSockets ?? [],
  };
}

export function insideIsland(island: TileRect, tileX: number, tileY: number): boolean {
  return (
    tileX >= island.tileX && tileX < island.tileX + island.widthTiles && tileY >= island.tileY && tileY < island.tileY + island.heightTiles
  );
}

/** The sea's sectors (§5 reveals the final island's): a grid of this many columns and as many rows. */
export const SECTOR_GRID = 3;

export interface Sector {
  /** 0 west to SECTOR_GRID - 1 east. */
  readonly column: number;
  /** 0 north to SECTOR_GRID - 1 south. */
  readonly row: number;
}

/**
 * The sector a tile lies in: column ⌊3 · tileX / widthTiles⌋, row ⌊3 · tileY / heightTiles⌋. On the 111-tile slice sea
 * the columns (and rows) are tiles 0–36, 37–73 and 74–110, so the map's mirror maps sectors onto sectors. Whatever
 * announces a sector (the intel module, the endgame reveal) must use this same formula.
 */
export function sectorOf(map: Pick<SeaMapDefinition, "widthTiles" | "heightTiles">, tileX: number, tileY: number): Sector {
  return { column: Math.floor((SECTOR_GRID * tileX) / map.widthTiles), row: Math.floor((SECTOR_GRID * tileY) / map.heightTiles) };
}

/**
 * The index of the socket that is the final island for a match: pure over the map and a 32-bit `secret`, an unsigned
 * integer the server draws from a cryptographic source for each match. Never pass the match's seed or anything else
 * public or derived from it: §3 requires that the final island cannot be recovered from a public seed, and the map is
 * public, so the secret is the only thing hiding the choice.
 *
 * The secret goes through the murmur3 finaliser (xor-shift 16, × 0x85ebca6b, xor-shift 13, × 0xc2b2ae35, xor-shift 16,
 * in `Math.imul` 32-bit arithmetic) before the reduction modulo the socket count, so every bit of the secret moves
 * the choice, not only its low bits. The finaliser permutes the 32-bit integers, so over all secrets each socket of a
 * power-of-two count is chosen equally often. It is a mixer, not a cryptographic hash: the secrecy comes from the
 * secret.
 */
export function chooseFinalSocket(map: Pick<SeaMapDefinition, "finalSockets">, secret: number): number {
  if (map.finalSockets.length === 0) throw new RangeError("the map has no final-island sockets");
  if (!Number.isInteger(secret) || secret < 0 || secret > 0xffffffff) throw new RangeError(`the secret must be an unsigned 32-bit integer, got ${secret}`);
  let mixed = secret;
  mixed ^= mixed >>> 16;
  mixed = Math.imul(mixed, 0x85ebca6b);
  mixed ^= mixed >>> 13;
  mixed = Math.imul(mixed, 0xc2b2ae35);
  mixed ^= mixed >>> 16;
  return (mixed >>> 0) % map.finalSockets.length;
}

/** The side of an island a tile lies on (N, E, S or W), from its offset to the island rectangle's centre. */
function sideOf(island: IslandSource, tileX: number, tileY: number): Compass {
  // Doubled offsets keep the rectangle's centre on an integer; scaling by the other side's length makes a long thin
  // island still read its ends as its ends.
  const dx = (2 * tileX + 1 - (2 * island.tileX + island.widthTiles)) * island.heightTiles;
  const dy = (2 * tileY + 1 - (2 * island.tileY + island.heightTiles)) * island.widthTiles;
  if (Math.abs(dx) >= Math.abs(dy)) return dx > 0 ? "E" : "W";
  return dy > 0 ? "S" : "N";
}

export function terrainAt(map: SeaMapDefinition, tileX: number, tileY: number): Terrain | undefined {
  if (tileX < 0 || tileY < 0 || tileX >= map.widthTiles || tileY >= map.heightTiles) return undefined;
  return map.terrain[tileY * map.widthTiles + tileX];
}

/** Ships sail on sea and docks. Anything outside the map counts as blocked. */
export function isNavigable(map: SeaMapDefinition, tileX: number, tileY: number): boolean {
  const kind = terrainAt(map, tileX, tileY);
  return kind === Terrain.Sea || kind === Terrain.Dock;
}

/** A readable name for a dock, for the HUD: "Palm Key, south dock". */
export function dockLabel(map: SeaMapDefinition, dockId: number): string {
  const dock = map.docks[dockId];
  if (dock === undefined) return "";
  const names: Record<Compass, string> = { E: "east", SE: "south-east", S: "south", SW: "south-west", W: "west", NW: "north-west", N: "north", NE: "north-east" };
  return `${map.islands[dock.island]?.name ?? "?"}, ${names[dock.side]} dock`;
}
    ".......................................................%.......................................................",
    ".......................................................%.......................................................",
    ".......................................................%.......................................................",
  ],
  islands: [
    { name: "Palm Key", theme: "tropical", tileX: 17, tileY: 17, widthTiles: 14, heightTiles: 12 },
    { name: "Ember Rock", theme: "volcanic", tileX: 80, tileY: 17, widthTiles: 14, heightTiles: 12 },
    { name: "Old Stones", theme: "ruin", tileX: 17, tileY: 82, widthTiles: 14, heightTiles: 12 },
    { name: "Mist Cay", theme: "mist", tileX: 80, tileY: 82, widthTiles: 14, heightTiles: 12 },
  ],
  spawnSlots: [
    { tileX: 31, tileY: 5, facing: "SW" },
    { tileX: 79, tileY: 5, facing: "SE" },
    { tileX: 105, tileY: 32, facing: "NW" },
    { tileX: 105, tileY: 78, facing: "SW" },
    { tileX: 79, tileY: 105, facing: "NE" },
    { tileX: 31, tileY: 105, facing: "NW" },
    { tileX: 5, tileY: 78, facing: "SE" },
    { tileX: 5, tileY: 32, facing: "NE" },
  ],
  hub: { tileX: 55, tileY: 55 },
  finalSockets: [
    { rect: { tileX: 41, tileY: 11, widthTiles: 5, heightTiles: 5 }, claimTile: { tileX: 43, tileY: 16 } },
    { rect: { tileX: 65, tileY: 11, widthTiles: 5, heightTiles: 5 }, claimTile: { tileX: 67, tileY: 16 } },
    { rect: { tileX: 41, tileY: 95, widthTiles: 5, heightTiles: 5 }, claimTile: { tileX: 43, tileY: 94 } },
    { rect: { tileX: 65, tileY: 95, widthTiles: 5, heightTiles: 5 }, claimTile: { tileX: 67, tileY: 94 } },
