import { DUEL_UNAVAILABLE_MESSAGE, MATCH_UNAVAILABLE_MESSAGE, PROTOCOL_VERSION, type DummyBehaviour } from "@pirate-sea-race/protocol";
import { startArena } from "./arenaScene.js";
import { createMatch, joinMatch, refusalMessage, serverEndpoint, type MatchRoom } from "./connection.js";
import { DuelClient } from "./duelClient.js";
import { createDuel, joinDuel, type DuelRoom } from "./duelConnection.js";
import { duelRoomTransport, SeaDuelRouter } from "./duelTransport.js";
import { renderHud, type ConnectionStatus } from "./hud.js";
import { InputSender } from "./inputSender.js";
import { KeyboardHelm, NEUTRAL_HELM } from "./keyboard.js";
import { MatchView, type ShipSnapshot } from "./matchView.js";
import { MatchGame } from "./seaScene.js";

const INPUT_INTERVAL_MS = 1000 / 60;

function element<T extends HTMLElement>(selector: string): T {
  const found = document.querySelector<T>(selector);
  if (found === null) throw new Error(`missing element ${selector}`);
  return found;
}

const landing = element<HTMLElement>("#landing");
const matchSection = element<HTMLElement>("#match");
const createButton = element<HTMLButtonElement>("#create-match");
const joinForm = element<HTMLFormElement>("#join-form");
const joinButton = element<HTMLButtonElement>("#join-match");
const codeInput = element<HTMLInputElement>("#join-code");
const errorText = element<HTMLElement>("#join-error");
const duelSection = element<HTMLElement>("#duel");
const duelHud = element<HTMLElement>("#duel-hud");
const seaHud = element<HTMLElement>("#hud");
const duelButtons = [element<HTMLButtonElement>("#create-duel"), element<HTMLButtonElement>("#practice-duel"), element<HTMLButtonElement>("#join-duel")];
const duelCodeInput = element<HTMLInputElement>("#duel-code");
const duelErrorText = element<HTMLElement>("#duel-error");
const endpoint = serverEndpoint(window.location);

element<HTMLElement>('[data-testid="landing-protocol"]').textContent = String(PROTOCOL_VERSION);

createButton.addEventListener("click", () => void connect(() => createMatch(endpoint)));
joinForm.addEventListener("submit", (event) => {
  event.preventDefault();
  void connect(() => joinMatch(endpoint, codeInput.value));
});

element<HTMLButtonElement>("#create-duel").addEventListener("click", () => void connectDuel(() => createDuel(endpoint, false)));
element<HTMLButtonElement>("#practice-duel").addEventListener("click", () => void connectDuel(() => createDuel(endpoint, true)));
element<HTMLFormElement>("#join-duel-form").addEventListener("submit", (event) => {
  event.preventDefault();
  void connectDuel(() => joinDuel(endpoint, duelCodeInput.value));
});

async function connectDuel(open: () => Promise<DuelRoom>): Promise<void> {
  for (const button of duelButtons) button.disabled = true;
  duelErrorText.textContent = "";
  try {
    const room = await open();
    // Development only: `?rtt=80&jitter=20` delays this socket both ways (README). Vite drops this branch, and the
    // module it imports, from the production build.
    if (import.meta.env.DEV) {
      const { applyDevLatency, devLatencyFromQuery } = await import("./devLatency.js");
      const latency = devLatencyFromQuery(window.location.search);
      if (latency !== undefined) applyDevLatency(room, latency);
    }
    enterDuel(room);
  } catch (error) {
    const message = refusalMessage(error);
    duelErrorText.textContent = message === MATCH_UNAVAILABLE_MESSAGE ? DUEL_UNAVAILABLE_MESSAGE : message;
    for (const button of duelButtons) button.disabled = false;
  }
}

/** The duel HUD's developer toggle drives whichever duel is showing. */
function wireHitboxToggle(current: () => DuelClient | undefined): void {
  const boxes = element<HTMLInputElement>("#show-boxes");
  boxes.addEventListener("change", () => {
    current()?.setShowBoxes(boxes.checked);
    boxes.blur();
  });
}

function enterDuel(room: DuelRoom): void {
  landing.hidden = true;
  duelSection.hidden = false;
  const duel = new DuelClient(duelRoomTransport(room), duelHud);
  wireHitboxToggle(() => duel);
  const dummy = element<HTMLSelectElement>("#dummy-select");
  dummy.addEventListener("change", () => {
    duel.setDummy(dummy.value as DummyBehaviour);
    dummy.blur();
  });
  const dummyControl = element<HTMLElement>("#dummy-control");
  const showDummyControl = () => {
    dummyControl.hidden = room.state?.practice !== true;
  };
  showDummyControl();
  room.onStateChange(showDummyControl);
  startArena(element<HTMLElement>("#arena"), duel);
}

async function connect(open: () => Promise<MatchRoom>): Promise<void> {
  setBusy(true);
  errorText.textContent = "";
  try {
    enterMatch(await open());
  } catch (error) {
    errorText.textContent = refusalMessage(error);
    setBusy(false);
  }
}

function setBusy(busy: boolean): void {
  createButton.disabled = busy;
  joinButton.disabled = busy;
}

function enterMatch(room: MatchRoom): void {
  landing.hidden = true;
  matchSection.hidden = false;

  const view = new MatchView(room.sessionId);
  const sender = new InputSender({ send: (type, message) => room.send(type, message) });
  const keyboard = new KeyboardHelm(window);
  const router = new SeaDuelRouter(room);
  let status: ConnectionStatus = "connected";
  let duel: { readonly key: string; readonly client: DuelClient } | undefined;
  let game: MatchGame | undefined;
  wireHitboxToggle(() => duel?.client);

  /**
   * A duel at sea (§6): when the room holds one for this player, the arena scene takes over the game and the duel HUD
   * the sea HUD's place, until the room lets the duel go; then the sea is back.
   */
  const followDuel = () => {
    const key = router.current();
    if (duel !== undefined && duel.key !== key) {
      duel.client.dispose();
      router.forget();
      duel = undefined;
      game?.showSea();
      duelSection.append(duelHud);
      seaHud.hidden = false;
    }
    if (duel === undefined && key !== undefined && game !== undefined) {
      const client = new DuelClient(router.transport(key), duelHud);
      duel = { key, client };
      seaHud.hidden = true;
      matchSection.append(duelHud);
      game.showArena(client);
    }
  };

  const refresh = () => {
    const state = room.state;
    if (state?.ships === undefined) return;
    const now = performance.now();
    const ships: ShipSnapshot[] = [...state.ships.values()];
    const grapples = [...(state.grapples?.values() ?? [])];
    const encounter = state.status?.get(room.sessionId);
    view.ingest(ships, now);
    view.ingestEncounters(grapples, state.markers?.values() ?? [], encounter, state.worldTick);
    sender.observeFrame(state.frame, now);
    renderHud(matchSection, {
      code: state.code,
      protocolVersion: state.protocolVersion,
      custom: state.custom,
      status,
      selfId: room.sessionId,
      players: state.players,
      ships,
      worldTick: state.worldTick,
      encounter: view.status(),
      grapples: view.grapples(),
    });
    followDuel();
  };

  room.onStateChange(refresh);
  room.onLeave(() => {
    status = "disconnected";
    refresh();
  });
  refresh();

  const inputTimer = window.setInterval(() => {
    // The helm is read even in a duel, so a key tapped there (J is also the light attack) is not kept for the sea.
    const helm = keyboard.helm();
    if (status === "connected") sender.update(duel === undefined ? helm : NEUTRAL_HELM, performance.now());
    else window.clearInterval(inputTimer);
  }, INPUT_INTERVAL_MS);

  game = new MatchGame(element<HTMLElement>("#game"), view);
  followDuel();
}
import { dockLabel, HEADING_COUNT, WORLD_STEPS_PER_SECOND } from "@pirate-sea-race/content";
import { defaultSimulationConfig, dockInReach, NOT_DOCKED, toTilePosition } from "@pirate-sea-race/simulation";
import { cssColor, slotColor, type GrappleSnapshot, type ShipSnapshot, type StatusSnapshot } from "./matchView.js";

export type ConnectionStatus = "connected" | "disconnected";

export interface HudModel {
  readonly code: string;
  readonly protocolVersion: number;
  readonly custom: boolean;
  readonly status: ConnectionStatus;
  readonly selfId: string;
  /** Players in the match, including those out of sight. */
  readonly players: number;
  /** The ships the server sent: the player's own and those in sight. */
  readonly ships: readonly ShipSnapshot[];
  /** The world tick of the last patch. */
  readonly worldTick: number;
  /** This player's encounter status, once the server sent it. */
  readonly encounter: StatusSnapshot | undefined;
  /** The grapples in sight, or aimed at this player. */
  readonly grapples: readonly GrappleSnapshot[];
}

/** Whole seconds left until a world tick, rounded up; 0 once it has passed. */
export function secondsUntil(tick: number, worldTick: number): number {
  return Math.max(0, Math.ceil((tick - worldTick) / WORLD_STEPS_PER_SECOND));
}

/** A duel's elapsed time as its marker shows it (§6): minutes and seconds since the duel began. */
export function elapsedText(startTick: number, worldTick: number): string {
  const seconds = Math.max(0, Math.floor((worldTick - startTick) / WORLD_STEPS_PER_SECOND));
  return `${Math.floor(seconds / 60)}:${String(seconds % 60).padStart(2, "0")}`;
}

const COMPASS = ["east", "south-east", "south", "south-west", "west", "north-west", "north", "north-east"] as const;

/** The compass point (of eight) from one position toward another; y grows south. */
export function compassToward(from: { x: number; y: number }, to: { x: number; y: number }): (typeof COMPASS)[number] {
  const turns = Math.atan2(to.y - from.y, to.x - from.x) / (2 * Math.PI);
  return COMPASS[(Math.round(turns * 8) + 8) % 8]!;
}

/** The compass point of a heading (of 64). */
export function compassOfHeading(heading: number): (typeof COMPASS)[number] {
  return COMPASS[Math.round((heading / HEADING_COUNT) * 8) % 8]!;
}

export interface HudLine {
  readonly text: string;
  /** What the line says, for tests and styling. */
  readonly state: string;
  /** Seconds left, where the line counts down. */
  readonly seconds?: number;
}

/**
 * The grapple (J, §6): aiming (this player's telegraph is out, with its aim), cooling down after a miss, not
 * available (in a duel or waiting to respawn), or ready.
 */
export function grappleLine(model: Pick<HudModel, "selfId" | "encounter" | "grapples" | "worldTick">): HudLine {
  const own = model.grapples.find((grapple) => grapple.attackerId === model.selfId);
  if (own !== undefined) return { text: `Grappling, aimed ${compassOfHeading(own.aim)}`, state: "aiming", seconds: secondsUntil(own.landTick, model.worldTick) };
  const status = model.encounter;
  if (status !== undefined && status.mode !== "sea") return { text: "", state: "unavailable" };
  const cooldown = status === undefined ? 0 : secondsUntil(status.cooldownUntil, model.worldTick);
  if (cooldown > 0) return { text: `J: grapple in ${cooldown} s`, state: "cooldown", seconds: cooldown };
  return { text: "J: grapple a ship ahead", state: "ready" };
}

/** A grapple aimed at this player (§6: escape before it lands), with the side it comes from. */
export function incomingLine(model: Pick<HudModel, "selfId" | "grapples" | "ships" | "worldTick">): HudLine {
  const incoming = model.grapples.find((grapple) => grapple.defenderId === model.selfId);
  if (incoming === undefined) return { text: "", state: "none" };
  const own = model.ships.find((ship) => ship.id === model.selfId);
  const attacker = model.ships.find((ship) => ship.id === incoming.attackerId);
  // Without both ships, the aim still says where it comes from: from the opposite side of its direction.
  const from = own !== undefined && attacker !== undefined ? compassToward(own, attacker) : compassOfHeading(incoming.aim + HEADING_COUNT / 2);
  return { text: `Incoming grapple from the ${from}! Sail out of range or out of its aim`, state: from, seconds: secondsUntil(incoming.landTick, model.worldTick) };
}

const PROTECTION_SOURCES: Record<string, string> = { spawn: "departure", win: "won a duel", draw: "drawn duel", respawn: "respawned" };

/** Escape protection (§6): nobody can grapple this player until it runs out (or it grapples someone). */
export function protectionLine(model: Pick<HudModel, "encounter" | "worldTick">): HudLine {
  const status = model.encounter;
  if (status === undefined || status.protection === "") return { text: "", state: "none" };
  const seconds = secondsUntil(status.protectedUntil, model.worldTick);
  return { text: `Protected for ${seconds} s (${PROTECTION_SOURCES[status.protection] ?? status.protection})`, state: status.protection, seconds };
}

/** The loser's wait out of the world (§6): 15 s from the end of the fight, then a dock. */
export function respawnLine(model: Pick<HudModel, "encounter" | "worldTick">): HudLine {
  const status = model.encounter;
  if (status === undefined || status.mode !== "respawning") return { text: "", state: "none" };
  const seconds = secondsUntil(status.respawnAt, model.worldTick);
  return { text: `Duel lost: respawning at a dock in ${seconds} s`, state: "respawning", seconds };
}

function writeLine(element: HTMLElement, line: HudLine): void {
  element.textContent = line.text;
  element.dataset["state"] = line.state;
  if (line.seconds === undefined) delete element.dataset["seconds"];
  else element.dataset["seconds"] = String(line.seconds);
}

function field(root: ParentNode, id: string): HTMLElement {
  const element = root.querySelector<HTMLElement>(`[data-testid="${id}"]`);
  if (element === null) throw new Error(`missing HUD field ${id}`);
  return element;
}

/** "Palm Key, south dock" when moored, "at sea" otherwise. */
export function dockText(dock: number): string {
  return dock === NOT_DOCKED ? "at sea" : dockLabel(defaultSimulationConfig.map, dock);
}

/**
 * What the player can do about docking right now, by the simulation's own rule (`dockInReach`; speed does not matter):
 * nothing to say when moored or far from any dock; otherwise press E.
 */
export function dockHint(ship: Pick<ShipSnapshot, "x" | "y" | "dock">): string {
  if (ship.dock !== NOT_DOCKED) return "";
  const config = defaultSimulationConfig;
  const berth = dockInReach(config, ship.x, ship.y);
  return berth === undefined ? "" : `Press E to dock at ${dockLabel(config.map, berth.id)}`;
}

/** Writes the match status and the latest authoritative (not interpolated) state of the visible ships. */
export function renderHud(root: ParentNode, model: HudModel): void {
  field(root, "hud-code").textContent = model.code;
  field(root, "hud-protocol").textContent = `v${model.protocolVersion}`;
  field(root, "hud-players").textContent = String(model.players);
  field(root, "hud-status").textContent = model.status;
  field(root, "hud-mode").textContent = model.custom ? "custom" : "standard";
  field(root, "hud-self").textContent = model.selfId;
  const own = model.ships.find((ship) => ship.id === model.selfId);
  const dock = field(root, "hud-dock");
  dock.textContent = own === undefined ? "" : dockText(own.dock);
  dock.dataset["dock"] = String(own?.dock ?? NOT_DOCKED);
  field(root, "hud-dock-hint").textContent = own === undefined ? "" : dockHint(own);
  writeLine(field(root, "hud-grapple"), grappleLine(model));
  writeLine(field(root, "hud-incoming"), incomingLine(model));
  writeLine(field(root, "hud-protection"), protectionLine(model));
  writeLine(field(root, "hud-respawn"), respawnLine(model));

  const list = field(root, "positions");
  const items = model.ships.map((ship) => {
    const item = document.createElement("li");
    item.dataset["shipId"] = ship.id;
    item.dataset["slot"] = String(ship.slot);
    item.dataset["x"] = String(ship.x);
    item.dataset["y"] = String(ship.y);
    item.dataset["heading"] = String(ship.heading);
    item.dataset["speed"] = String(ship.speed);
    item.dataset["dock"] = String(ship.dock);
    const swatch = document.createElement("span");
    swatch.className = "swatch";
    swatch.style.background = cssColor(slotColor(ship.slot));
    const tile = toTilePosition(defaultSimulationConfig, ship.x, ship.y);
    const who = ship.id === model.selfId ? "you" : ship.id;
    item.append(swatch, `${who}: tile ${tile.tileX},${tile.tileY}, heading ${ship.heading}, speed ${ship.speed}`);
    return item;
  });
  list.replaceChildren(...items);
}
import { INTERPOLATION_DELAY_MS, SnapshotBuffer } from "./interpolation.js";

/** A ship as the server last sent it: only the client's own ship and ships in its sight ever arrive (§16). */
export interface ShipSnapshot {
  readonly id: string;
  readonly slot: number;
  readonly x: number;
  readonly y: number;
  readonly heading: number;
  readonly speed: number;
  /** The dock it is moored at, or -1 at sea. */
  readonly dock: number;
}

/** A telegraphed grapple (§6) as the server last sent it: only those whose attacker is in sight, or aimed at us. */
export interface GrappleSnapshot {
  readonly attackerId: string;
  readonly defenderId: string;
  /** The aim, a heading of 64 locked when the grapple started. */
  readonly aim: number;
  readonly startTick: number;
  readonly landTick: number;
}

/** A duel marker (§6) as the server last sent it: only those in sight. */
export interface MarkerSnapshot {
  readonly x: number;
  readonly y: number;
  /** The world tick the duel began; its elapsed time counts from here. */
  readonly startTick: number;
}

/** This player's own encounter status (§6): its mode, protection, grapple cooldown and respawn, in world ticks. */
export interface StatusSnapshot {
  readonly mode: string;
  readonly protection: string;
  readonly protectedUntil: number;
  readonly cooldownUntil: number;
  readonly respawnAt: number;
}

/** Placeholder ship colours by spawn slot. */
const SLOT_COLORS = [0xf4b942, 0xe5484d, 0x46a758, 0xb66ee8, 0xf76b15, 0x3dd6d0, 0xf2f2f2, 0xd6409f] as const;

export function slotColor(slot: number): number {
  return SLOT_COLORS[slot % SLOT_COLORS.length]!;
}

export function cssColor(color: number): string {
  return `#${color.toString(16).padStart(6, "0")}`;
}

/**
 * The client's picture of the match: the latest decoded server state of each visible ship (for the HUD) and a
 * snapshot history per ship (for interpolated drawing). A ship that leaves the decoded state is forgotten at once.
 */
export class MatchView {
  private readonly latest = new Map<string, ShipSnapshot>();
  private readonly buffers = new Map<string, SnapshotBuffer>();
  private encounter: { grapples: GrappleSnapshot[]; markers: MarkerSnapshot[]; status: StatusSnapshot | undefined; worldTick: number } = {
    grapples: [],
    markers: [],
    status: undefined,
    worldTick: 0,
  };

  constructor(readonly selfId: string) {}

  /** The encounter state the server last sent: grapples and markers in sight, and this player's status. */
  ingestEncounters(grapples: Iterable<GrappleSnapshot>, markers: Iterable<MarkerSnapshot>, status: StatusSnapshot | undefined, worldTick: number): void {
    this.encounter = {
      grapples: [...grapples].map(({ attackerId, defenderId, aim, startTick, landTick }) => ({ attackerId, defenderId, aim, startTick, landTick })),
      markers: [...markers].map(({ x, y, startTick }) => ({ x, y, startTick })),
      status: status === undefined ? undefined : { ...pickStatus(status) },
      worldTick,
    };
  }

  grapples(): readonly GrappleSnapshot[] {
    return this.encounter.grapples;
  }

  markers(): readonly MarkerSnapshot[] {
    return this.encounter.markers;
  }

  status(): StatusSnapshot | undefined {
    return this.encounter.status;
  }

  /** The world tick of the last patch (20 a second). */
  worldTick(): number {
    return this.encounter.worldTick;
  }

  ingest(ships: Iterable<ShipSnapshot>, now: number): void {
    const seen = new Set<string>();
    for (const ship of ships) {
      seen.add(ship.id);
      const { id, slot, x, y, heading, speed, dock } = ship;
      this.latest.set(id, { id, slot, x, y, heading, speed, dock });
      let buffer = this.buffers.get(id);
      if (buffer === undefined) this.buffers.set(id, (buffer = new SnapshotBuffer()));
      buffer.push(now, x, y);
    }
    for (const id of [...this.latest.keys()]) {
      if (seen.has(id)) continue;
      this.latest.delete(id);
      this.buffers.delete(id);
    }
  }

  ships(): ShipSnapshot[] {
    return [...this.latest.values()];
  }

  ship(id: string): ShipSnapshot | undefined {
    return this.latest.get(id);
  }

  /** Where to draw a ship at `now`, interpolated INTERPOLATION_DELAY_MS in the past. */
  renderPosition(id: string, now: number): { x: number; y: number } | undefined {
    return this.buffers.get(id)?.sample(now - INTERPOLATION_DELAY_MS);
  }
}

function pickStatus({ mode, protection, protectedUntil, cooldownUntil, respawnAt }: StatusSnapshot): StatusSnapshot {
  return { mode, protection, protectedUntil, cooldownUntil, respawnAt };
}

