1	import { matchMaker } from "colyseus";
2	import { expect } from "vitest";
3	import { isNavigable, seaMap } from "@pirate-sea-race/content";
4	import type { MatchRoom } from "@pirate-sea-race/server";
5	import { defaultSimulationConfig, hullPathIsClear, tileCentre } from "@pirate-sea-race/simulation";
6	import { duelInput } from "@pirate-sea-race/simulation/duel";
7	import { HeadlessClient, type DuelScript, type HeadlessClientOptions } from "@pirate-sea-race/test-tools";
8	
9	/**
10	 * What the duel-at-sea tests share: the open stretch of sea they sail on, a pair of players placed on it, and the
11	 * scripted fighters. Each test file starts its own server; tests in a file run at once, one match each.
12	 */
13	
14	/** The row three tiles south of the hub, which the map keeps clear for a hull 20 tiles either side of the hub. */
15	export const OPEN_ROW = seaMap.hub.tileY + 3;
16	export const HUB_X = seaMap.hub.tileX;
17	export const TILE = seaMap.subUnitsPerTile;
18	/** Headings of 64: east, south, west, north. */
19	export const EAST = 0;
20	export const SOUTH = 16;
21	export const WEST = 32;
22	export const NORTH = 48;
23	
24	/** Collects a test's clients and has them leave when that test finishes (tests in a file run at once). */
25	export function tracker(onTestFinished: (fn: () => Promise<void>) => void): (client: HeadlessClient) => void {
26	  const clients: HeadlessClient[] = [];
27	  onTestFinished(async () => {
28	    await Promise.all(clients.map((client) => client.leave()));
29	  });
30	  return (client) => void clients.push(client);
31	}
32	
33	export function roomOf(client: HeadlessClient): MatchRoom {
34	  return matchMaker.getLocalRoomById(client.room.roomId) as unknown as MatchRoom;
35	}
36	
37	export interface Seat {
38	  readonly tileX: number;
39	  readonly tileY: number;
40	  readonly heading: number;
41	}
42	
43	/** Whether a hull can sail the straight line between two tile centres (and so the tiles between see each other). */
44	export function openWater(from: Seat, to: Seat): boolean {
45	  const a = tileCentre(defaultSimulationConfig, from.tileX, from.tileY);
46	  const b = tileCentre(defaultSimulationConfig, to.tileX, to.tileY);
47	  return isNavigable(seaMap, from.tileX, from.tileY) && hullPathIsClear(defaultSimulationConfig, a.x, a.y, b.x, b.y);
48	}
49	
50	/** Players in one match, created in order (the first creates it), then placed at rest on their seats. */
51	export async function playersAt(
52	  endpoint: string,
53	  seats: readonly Seat[],
54	  track: (client: HeadlessClient) => void,
55	  options: { readonly endpoints?: readonly string[]; readonly clients?: readonly HeadlessClientOptions[] } = {},
56	): Promise<HeadlessClient[]> {
57	  const clients: HeadlessClient[] = [];
58	  for (const [index, seat] of seats.entries()) {
59	    const via = options.endpoints?.[index] ?? endpoint;
60	    const client = index === 0 ? await HeadlessClient.create(via, options.clients?.[0]) : await HeadlessClient.join(via, clients[0]!.code, options.clients?.[index]);
61	    track(client);
62	    clients.push(client);
63	    expect(openWater(seat, seat)).toBe(true);
64	  }
65	  await clients[0]!.waitFor(() => clients[0]!.playerCount === seats.length);
66	  for (const [index, seat] of seats.entries()) await clients[index]!.placeShip(endpoint, seat);
67	  return clients;
68	}
69	
70	/**
71	 * The host (attacker) and the guest in grapple range on the open row, `apart` tiles apart around the hub: the host
72	 * west facing east, the guest east facing `guestHeading` (west by default, toward the host).
73	 */
74	export async function pairInRange(
75	  endpoint: string,
76	  track: (client: HeadlessClient) => void,
77	  options: {
78	    readonly apart?: number;
79	    readonly guestHeading?: number;
80	    readonly endpoints?: readonly string[];
81	    readonly clients?: readonly HeadlessClientOptions[];
82	  } = {},
83	): Promise<{ host: HeadlessClient; guest: HeadlessClient }> {
84	  const apart = options.apart ?? 6;
85	  const host: Seat = { tileX: HUB_X - Math.floor(apart / 2), tileY: OPEN_ROW, heading: EAST };
86	  const guest: Seat = { tileX: host.tileX + apart, tileY: OPEN_ROW, heading: options.guestHeading ?? WEST };
87	  expect(openWater(host, guest)).toBe(true);
88	  const [first, second] = await playersAt(endpoint, [host, guest], track, options);
89	  await first!.waitFor(() => first!.ship(second!.sessionId) !== undefined);
90	  return { host: first!, guest: second! };
91	}
92	
93	/** Grapples: the host taps J, and both fighters' duel reaches its countdown. */
94	export async function grapple(host: HeadlessClient, guest: HeadlessClient): Promise<void> {
95	  host.tapGrapple();
96	  for (const client of [host, guest]) await client.waitFor(() => client.fighter.phase === "countdown", 3000);
97	}
