  type MatchState,
  type Placement,
  type PlayerInput,
} from "@pirate-sea-race/simulation";
import type { PlayerIndex } from "@pirate-sea-race/simulation/duel";
import {
  createEncounterConfig,
  createEncounterState,
  duelOf,
  stepEncounters,
  type DuelReport,
  type EncounterConfig,
  type EncounterEvent,
  type EncounterPlayerInput,
  type EncounterState,
} from "@pirate-sea-race/simulation/encounters";
import type { DuelAuthority } from "@pirate-sea-race/simulation/netcode";
import {
  addPlayer,
  advanceLedger,
  cacheRubbings,
  cancelChannel,
  checkLedger,
  chooseTheft,
  disconnectPlayer,
  eligibleTheftTypes,
  expireReservation,
  findDuel,
  findPlayer,
  heldTypes,
  objectiveRules,
