:root {
  color-scheme: dark;
  font-family: system-ui, sans-serif;
  background: #06202f;
  color: #e8f1f5;
}

body {
  margin: 0;
}

[hidden] {
  display: none !important;
}

main {
  padding: 1.5rem;
}

#landing:not([hidden]) {
  max-width: 24rem;
  margin: 4rem auto;
  display: grid;
  gap: 1rem;
}

h1 {
  margin: 0;
}

.tagline,
.version,
.hint {
  color: #9bb8c6;
  margin: 0;
}

button,
input {
  font: inherit;
  padding: 0.5rem 0.75rem;
}

#join-form {
  display: flex;
  gap: 0.5rem;
  align-items: center;
}

#join-code {
  text-transform: uppercase;
  width: 7rem;
}

#join-error {
  color: #ff9b8a;
  min-height: 1.5em;
  margin: 0;
}

#match:not([hidden]) {
  display: flex;
  gap: 1.5rem;
  align-items: flex-start;
}

#game {
  flex: none;
}

#game canvas {
  display: block;
}

#hud {
  max-width: 22rem;
}

#hud dl {
  display: grid;
  grid-template-columns: auto auto;
  gap: 0.25rem 1rem;
  margin: 0;
}

#hud dt {
  color: #9bb8c6;
}

#hud dd {
  margin: 0;
  font-variant-numeric: tabular-nums;
}

#hud dd.warning {
  color: #ff8a80;
  font-weight: 600;
}

#hud ul {
  list-style: none;
  padding: 0;
  font-variant-numeric: tabular-nums;
}

.swatch {
  display: inline-block;
  width: 0.75em;
  height: 0.75em;
  border-radius: 50%;
  margin-right: 0.4em;
}

.duel-entry {
  display: grid;
  gap: 0.75rem;
  border-top: 1px solid #1f4d66;
  padding-top: 1rem;
}

import type { IslandTheme } from "@pirate-sea-race/content";

/**
 * The scene's placeholder palette, kept free of Phaser so the browser tests can check the canvas against it. None of
 * these is near a ship colour, so a ship's colour on the canvas is always a ship.
 */
export const SEA_COLOR = 0x0b3d5c;
export const GRID_COLOR = 0x145374;
export const SHOAL_COLOR = 0x2e7d86;
export const SHOAL_FLECK = 0x4f9aa0;
export const DOCK_COLOR = 0x8b5a2b;
export const DOCK_PLANK = 0x6b4220;
export const LAND_COLORS: Readonly<Record<IslandTheme, number>> = { tropical: 0x6b8e23, volcanic: 0x5b4a45, ruin: 0x9a8f73, mist: 0x7d8a99 };
export const FOG_COLOR = 0x16202a;
export const OWN_RING_COLOR = 0xfff3b0;
export const SIGHT_COLOR = 0x9bd1e5;
/** A grapple's telegraph (§6): this player's own aim, one aimed at this player, and anyone else's in sight. */
export const AIM_COLOR = 0xc9e36b;
export const INCOMING_COLOR = 0xff1f1f;
export const TELEGRAPH_COLOR = 0xffd0a0;
/** A duel marker's crossed swords. */
export const MARKER_COLOR = 0xc0c8d0;
/** The ring of a protected ship (§6's escape protection). */
export const PROTECTION_COLOR = 0x7fdbff;

