130:    const guest = await track(HeadlessDuelClient.join(endpoint, host.code));
152:  it("lands a jab and a throw pressed J then K one or two frames apart, and a jab when K comes three frames late", async () => {
154:      const player = await track(HeadlessDuelClient.create(endpoint, { practice: true, tickMs: 1_000_000 }));
171:  it("never lets late input rewrite a stepped frame, and repeats a missing input for 250 ms before neutral", async () => {
172:    const player = await track(HeadlessDuelClient.create(endpoint, { practice: true, tickMs: 1_000_000 }));
190:  it("switches the practice dummy to guarding, so the same jab is blocked", async () => {
