205:describe("duel reconnection (§12)", () => {
206:  async function startDuel(dropperThroughProxy: boolean): Promise<{ host: HeadlessDuelClient; guest: HeadlessDuelClient; proxy: ImpairmentProxy }> {
208:    proxies.push(proxy);
209:    const host = await track(HeadlessDuelClient.create(endpoint));
210:    const guest = await track(HeadlessDuelClient.join(dropperThroughProxy ? proxy.endpoint : endpoint, host.code));
219:  it("gives a dropped player neutral input after the held-input timeout, and lets them rejoin and continue", async () => {
220:    const { host, guest, proxy } = await startDuel(true);
251:  async function startDuelBothBehindProxies(): Promise<{ host: HeadlessDuelClient; guest: HeadlessDuelClient; hostProxy: ImpairmentProxy; guestProxy: ImpairmentProxy }> {
253:    proxies.push(hostProxy, guestProxy);
254:    const host = await track(HeadlessDuelClient.create(hostProxy.endpoint));
255:    const guest = await track(HeadlessDuelClient.join(guestProxy.endpoint, host.code));
264:  it("forfeits the player whose reconnection window runs out first, while the other is still inside their own window", async () => {
